#ifndef _IES_AUTO_MIBS_FLAGS_net_mx_portmirror_c_
#define _IES_AUTO_MIBS_FLAGS_net_mx_portmirror_c_



ies_handle_t 
ies_auto_mibs_setup_entry_flags_net_mx_portmirror
(
    struct ies_auto_mibs_entry *entry
)
{


    if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri, "portMirror/enable") ) 
    {

        IES_FLAG_BITS_SET(IES_FLAG_SNMP_REPLACE_TRUTH_VALUE, entry->flags);

    }
	else
	if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri, "portMirror/remoteSpanIntmedRole") ) 
    {

        IES_FLAG_BITS_SET(IES_FLAG_SNMP_REPLACE_TRUTH_VALUE, entry->flags);

    }
    else
	if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri, "portMirror/remoteSpanIntmedVlanIdSecond") ) 
    {
        IES_FLAG_BITS_SET(IES_FLAG_SNMP_URI_CONFIG_CHAIN, entry->flags);
    }
    else
	if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri, "portMirror/remoteSpanIntmedVlanId") ) 
    {
        IES_FLAG_BITS_SET(IES_FLAG_SNMP_URI_CONFIG_CHAIN, entry->flags);
    }
    else
    if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri, "portMirror/portMirrorTable/") ) 
    {

        if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "entryEnable") ) 
        {
            IES_FLAG_BITS_SET(IES_FLAG_SNMP_REPLACE_TRUTH_VALUE, entry->flags);
            IES_FLAG_BITS_SET(IES_FLAG_SNMP_URI_CONFIG_CHAIN, entry->flags);
        }
        else if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "reflectPortMode") )
        {
            IES_FLAG_BITS_SET(IES_FLAG_SNMP_REPLACE_TRUTH_VALUE, entry->flags);
        }
#if defined(MOXA_MIRROR_VLAN_MIRROR)
#if defined(BCM_ROBO2_XSDK)

        else if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "destPortTable") || \
                  IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "sourcePortRxTable") || \
                  IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "sourcePortTxTable") || \
                  IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "sourcePortChRxTable") || \
                  IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "sourcePortChTxTable") || \
                  IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "remoteSpanVlanId") || \
                  IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "sourceVlanRxTable") || \
                  IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "sourceVlanTxTable"))

#else

        else if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "destPortTable") || \
                  IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "sourcePortRxTable") || \
                  IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "sourcePortTxTable") || \
                  IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "sourcePortChRxTable") || \
                  IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "sourcePortChTxTable") || \
                  IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "remoteSpanVlanId") || \
                  IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "sourceVlanRxTable"))
#endif
#else
        else if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "destPortTable") || \
                  IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "sourcePortRxTable") || \
                  IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "sourcePortTxTable") || \
                  IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "sourcePortChRxTable") || \
                  IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "sourcePortChTxTable") || \
                  IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "remoteSpanVlanId"))
#endif
        {
            IES_FLAG_BITS_SET(IES_FLAG_SNMP_URI_CONFIG_CHAIN, entry->flags);
        }

    }
    return IES_NOERR;
}



#endif //_IES_AUTO_MIBS_FLAGS_net_mx_portmirror_c_

