int32_t moxaSnmpHandle_UtilCfgGetURIConfigString( char        *uriPath,
                                                  char        *configStr,
                                                  int32_t      configStrMax )
{
    JSON_Value *jsonVal    = NULL;
    char       *jsonValStr = NULL;
    if ( moxaSnmpHandle_UtilCfgGetURIConfig(uriPath, &jsonVal) != 0 )
    {
        json_value_free(jsonVal);
        jsonVal = NULL;
        LibUtil_DbgTrace( kDbgFlgIssUriSNMP, "%% %s@%d : can't UtilCfgGetURIConfig\n",
            __func__, __LINE__ );
        return (-1);
    }
    jsonValStr = json_serialize_to_string(jsonVal);
    if ( jsonValStr == NULL )
    {
        LibUtil_DbgTrace( kDbgFlgIssUriSNMP, "%% %s@%d : can't json_serialize_to_string\n",
            __func__, __LINE__ );
        json_value_free(jsonVal);
        jsonVal = NULL;
        return (-1);
    }
    snprintf(configStr, configStrMax, "%s", jsonValStr);
    json_free_serialized_string(jsonValStr);
    json_value_free(jsonVal);
    jsonVal = NULL;
