36	/// decided. Getting it wrong is silent: net-snmp's compiled-in default is the
37	/// unix socket /var/agentx/master, init succeeds either way, and the subagent
38	/// then retries a connection that will never be accepted.
39	const AGENTX_SOCKET: &str = "tcp:127.0.0.1:705";
