68	///
69	/// Returns only on error; the caller decides whether that is fatal. It is not:
70	/// the framework's HTTP service is unaffected by the subagent being down, which
71	/// is what makes this task reversible.
72	pub async fn run_subagent() -> Result<(), Box<dyn std::error::Error>> {
73	    let mut session = Session::init(AGENTX_NAME, Some(AGENTX_SOCKET), AGENTX_PING_INTERVAL)?;
74	    // "started", not "connected": init only enables subagent mode and asks
75	    // net-snmp to connect. Whether the session is up is visible on the master
76	    // (ss -tnp | grep 705), not from this return value.
77	    mx_notice!(
78	        MODULE_LIST_ID,
79	        &format!(
80	            "AgentX subagent {AGENTX_NAME} started, master {AGENTX_SOCKET}, \
81	             ping {}s",
82	            AGENTX_PING_INTERVAL.as_secs()
83	        )
84	    );
