86	    // No register_arc calls: see the module comment.
87	
88	    // net-snmp's descriptor set changes when the AgentX session reconnects, so
89	    // it is re-queried every iteration. The AsyncFd registrations are kept
90	    // across iterations for the descriptors that did not change: tokio's epoll
91	    // registration is edge-triggered, and dropping and recreating it on every
92	    // wake-up can lose a readiness edge for data already sitting in the socket.
93	    let mut registered: HashMap<RawFd, AsyncFd<RawFd>> = HashMap::new();
94	
95	    loop {
96	        let info = session.select_info()?;
97	
98	        registered.retain(|fd, _| info.fds.contains(fd));
99	        for &fd in &info.fds {
100	            if !registered.contains_key(&fd) {
101	                registered.insert(fd, AsyncFd::with_interest(fd, Interest::READABLE)?);
102	            }
103	        }
104	
105	        if registered.is_empty() {
106	            // Nothing to watch. Honour net-snmp's deadline if it gave one, and
107	            // otherwise come back shortly rather than blocking forever.
108	            tokio::time::sleep(info.timeout.unwrap_or(IDLE_POLL)).await;
109	            session.handle_timeout();
110	            continue;
111	        }
112	
113	        let ready_fd = wait_for_readable(&registered, info.timeout).await;
114	
115	        match ready_fd {
116	            Some(fd) => session.handle_read(fd),
117	            None => session.handle_timeout(),
118	        }
119	    }
120	}
