122	/// Wait until one of the descriptors is readable, or the deadline expires.
123	///
124	/// Returns the descriptor that became readable, or `None` on timeout.
125	async fn wait_for_readable(
126	    registered: &HashMap<RawFd, AsyncFd<RawFd>>,
127	    timeout: Option<Duration>,
128	) -> Option<RawFd> {
129	    let readable = async {
130	        let waits = registered
131	            .iter()
132	            .map(|(&fd, async_fd)| Box::pin(async move { (fd, async_fd.readable().await) }));
133	
134	        let ((fd, guard), _, _) = futures_util::future::select_all(waits).await;
135	
136	        // Clearing readiness is what stops the next readable() returning
137	        // immediately and spinning: snmp_read2() drains the socket, so the
138	        // edge has been consumed by the time this returns.
139	        if let Ok(mut guard) = guard {
140	            guard.clear_ready();
141	        }
142	        fd
143	    };
144	
145	    match timeout {
146	        Some(deadline) => tokio::time::timeout(deadline, readable).await.ok(),
147	        None => Some(readable.await),
148	    }
149	}
150	
151	/// Start the subagent on the current thread and keep the process running if it
152	/// cannot start.
153	///
154	/// `spawn_local`, not `spawn`: the future is `!Send` because every net-snmp
155	/// call has to stay on one thread. `#[actix_web::main]` already runs on a
156	/// current-thread runtime with a LocalSet, so this needs no runtime of its own.
157	pub fn spawn() {
158	    tokio::task::spawn_local(async {
159	        if let Err(e) = run_subagent().await {
160	            mx_error!(MODULE_LIST_ID, &format!("AgentX subagent stopped: {e}"));
161	        }
162	    });
163	}
