282	        &mut self,
283	        plugins: &mut plugins_moxa_framework::status::Plugins,
284	        path: &str,
285	        userinfo: &user_info::UserInfo,
286	        query: &QString,
287	    ) -> Result<serde_json::Value, ErrorCommon> {
