289	            method: http::Method::GET,
290	            path,
291	            userinfo: Some(userinfo.clone()),
292	            api_key: None,
293	            permissions: None,
294	        };
295	
296	        if path.is_empty() {
297	            let mut return_status = serde_json::json!(null);
298	
299	            for status_name in &self
300	                ._cache_info
301	                .keys()
302	                .map(|x| x.to_owned())
303	                .collect::<Vec<String>>()
304	            {
305	                if !self._check_status_permission(
306	                    plugins,
307	                    path,
308	                    userinfo,
309	                    status_name,
310	                    &request_info,
311	                )? {
312	                    continue;
313	                }
314	                self._update_status_cache(plugins, path, status_name, &request_info);
315	                return_status[status_name] = self._status[status_name].clone();
316	            }
317	
318	            return Ok(return_status);
319	        }
320	
321	        let path_vec: Vec<&str> = path.split('/').filter(|s| &"" != s).collect();
322	        let status_name = path_vec
323	            .first()
324	            .ok_or_else(|| ErrorCommon::new(ErrorType::InvalidRequestUri, path))?;
325	
326	        if !self._check_status_permission(plugins, path, userinfo, status_name, &request_info)? {
327	            return Err(ErrorCommon::new(ErrorType::PermissionDenied, path));
328	        }
329	
330	        self._update_status_cache(plugins, path, status_name, &request_info);
331	        self._get_status_by_path(path, query)
332	    }
