//! Module supporting status operation.

use std::cmp;
use std::collections::HashMap;

use actix_web::http;
use qstring::QString;
use serde::{Deserialize, Serialize};

use app_moxa_token_module as moxa_token;
use lib_moxa_rust_debug_log_ng::mx_error;
use lib_moxa_rust_debug_log_ng::{lib_moxa_debug_log_ng_syslog, LibMoxaDebugLogNgLogLevel};
use rust_moxa_common::{
    common_error::{ErrorCommon, ErrorType},
    err_return, none_return, request_info, user_info, utils,
};

const MODULE_LIST_ID: &str = "status_layer.operation";

#[derive(Debug, Serialize, Deserialize, Clone)]
struct CacheInfo {
    last_cache_time: u64,
    cache_timeout: u64,
    userinfo: Option<user_info::UserInfo>,
    plugin_name: String,
}

#[derive(Debug)]
pub struct StatusOperation {
    _status: serde_json::Value,
    _cache_info: HashMap<String, CacheInfo>,
}

// impl Default for StatusOperation {
//     fn default() -> Self {
//         Self::new()
//     }
// }

/// Class providing status operation.
impl StatusOperation {
    pub fn new(plugins_status: &mut plugins_moxa_framework::status::Plugins) -> StatusOperation {
        let mut _status = serde_json::json!(null);
        let mut _cache_info = HashMap::new();

        for plugin in plugins_status.plugins() {
            let status_name = plugin.get_name();
            _status[status_name] = serde_json::json!(null);
            _cache_info.insert(
                status_name.to_owned(),
                CacheInfo {
                    last_cache_time: 0,
                    cache_timeout: plugin.get_cache_timeout_in_second(),
                    userinfo: None,
                    plugin_name: plugin.get_name().to_owned(),
                },
            );
        }

        StatusOperation {
            _status,
            _cache_info,
        }
    }

    // Rust: following code is not necessary since Rust is strong-type language
    /*
    def _validate_userinfo(self, userinfo):
        # pylint: disable=no-self-use
        if "username" not in userinfo.keys():
            return False

        if "role" not in userinfo.keys():
            return False

        if "from_ip" not in userinfo.keys():
            return False

        if "nonce" not in userinfo.keys():
            return False

        if userinfo["role"] != "user" and \
            userinfo["role"] != "supervisor" and \
            userinfo["role"] != 'admin':
            return False

        return True
    */

    /// ```text
    /// Extract and validate user information from JWT token.
    ///
    /// Args:
    ///     auth (str): JWT token of login user.
    ///     remote_ip (str): IP of login user.
    ///
    /// Returns:
    ///     userinfo if token is valid, or None if token is invalid.
    /// ```
    pub fn validate_and_get_userinfo(
        &self,
        moxa_token_db: &moxa_token::TokenDb,
        path: &str,
        //------------------------------
        auth: Option<&str>,
        remote_ip: Option<&str>,
    ) -> Result<user_info::UserInfo, ErrorCommon> {
        match moxa_token_db.validate(
            auth.ok_or_else(|| ErrorCommon::new(ErrorType::InvalidAuthenticationInfo, path))?,
            remote_ip
                .ok_or_else(|| ErrorCommon::new(ErrorType::InvalidAuthenticationInfo, path))?,
        ) {
            Err(e) => {
                mx_error!(
                    MODULE_LIST_ID,
                    &format!("validate_and_get_userinfo failed: Err: {e:?}")
                );
                Err(ErrorCommon::new(ErrorType::InvalidAuthenticationInfo, path))
            }
            Ok((user_info, _)) => Ok(user_info),
        }
    }

    /// ```text
    /// Run permission check for status request.
    ///
    /// Args:
    ///     status_name (str): name if requesting status.
    ///     request_info (status_plugin.RequestInfo): information of status
    ///                                                 request.
    ///
    /// Returns:
    ///     True if permission granted, or False if not permitted.
    /// ```
    fn _check_status_permission(
        &mut self,
        plugins: &mut plugins_moxa_framework::status::Plugins,
        path: &str,
        userinfo: &user_info::UserInfo,
        //------------------------------
        status_name: &str,
        request_info: &request_info::RequestInfo,
    ) -> Result<bool, ErrorCommon> {
        // Rust: the `status_name` is as the same as the cache_info['plugin_name']
        let plugin = plugins
            .plugin(status_name)
            .ok_or_else(|| ErrorCommon::new(ErrorType::InvalidRequestUri, path))?;
        Ok(plugin.check_permission(userinfo, request_info))
    }

    /// ```text
    /// Update internal status cache.
    ///
    /// Args:
    ///     status_name (str): name if requesting status.
    ///     request_info (status_plugin.RequestInfo): information of status
    ///                                                 request.
    /// ```
    fn _update_status_cache(
        &mut self,
        plugins: &mut plugins_moxa_framework::status::Plugins,
        path: &str,
        //------------------------------
        status_name: &str,
        request_info: &request_info::RequestInfo,
    ) {
        let cache_info = none_return!(self._cache_info.get_mut(status_name));
        let plugin = none_return!(plugins.plugin(status_name));

        let now = utils::uptime();
        // Force cache update if requested by different user
        match &cache_info.userinfo {
            None => cache_info.last_cache_time = 0,
            Some(t) => {
                if t != request_info.userinfo.as_ref().unwrap() {
                    cache_info.last_cache_time = 0;
                }
            }
        }

        if now - cache_info.last_cache_time < cache_info.cache_timeout {
            return;
        }

        cache_info.last_cache_time = now;
        cache_info.userinfo = Some(request_info.userinfo.as_ref().unwrap().clone());

        self._status[status_name] = err_return!(plugin.get_status(path, request_info));
    }

    /// ```text
    /// Get status value by path.
    ///
    /// Args:
    ///     path (str): path of requesting status. Supports mapping status
    ///                 structure into multi-level URI as config layer.
    ///     query (ImmutableMultiDict): query string in URL.
    ///
    /// Returns:
    ///     object containing requesting status value, or None on error or not
    ///     found.
    /// ```
    fn _get_status_by_path(
        &self,
        path: &str,
        query: &QString,
    ) -> Result<serde_json::Value, ErrorCommon> {
        let mut return_status = &self._status;

        let path_vec: Vec<&str> = path.split('/').filter(|s| &"" != s).collect();
        for attribute in path_vec {
            if attribute.is_empty() {
                continue;
            }

            return_status = match attribute.parse::<usize>() {
                Ok(t) => &return_status[t],
                Err(_) => &return_status[attribute],
            };

            if return_status.is_null() {
                return Ok(return_status.clone());
            }
        }

        // Handle range
        if return_status.is_array() && !query.is_empty() {
            let page = query.get("page");
            let per_page = query.get("per_page");

            if let (Some(page_str), Some(per_page_str)) = (page, per_page) {
                let page: usize = page_str.parse().map_err(|_| {
                    ErrorCommon::new(ErrorType::InvalidArrayRangeRequest, path)
                        .page(page_str, per_page_str)
                })?;
                let per_page: usize = per_page_str.parse().map_err(|_| {
                    ErrorCommon::new(ErrorType::InvalidArrayRangeRequest, path)
                        .page(page_str, per_page_str)
                })?;

                let start_index = (page - 1) * per_page;
                let end_index = cmp::min(page * per_page, return_status.as_array().unwrap().len());

                // unwrap() is ok
                if start_index > return_status.as_array().unwrap().len() {
                    return Err(ErrorCommon::new(ErrorType::InvalidArrayRangeRequest, path)
                        .page(page_str, per_page_str));
                }

                return Ok(serde_json::json!(
                    // unwrap() is ok
                    return_status.as_array().unwrap()[start_index..end_index]
                ));
            } else if page.is_some() || per_page.is_some() {
                return Err(ErrorCommon::new(ErrorType::InvalidArrayRangeRequest, path)
                    .page(page.unwrap_or("null"), per_page.unwrap_or("null")));
            }
        }

        Ok(return_status.clone())
    }

    /// ```text
    /// Get status value by path.
    ///
    /// Check permission and return status if permitted.
    ///
    /// Args:
    ///     path (str): path of requesting status. Supports mapping status
    ///                 structure into multi-level URI as config layer.
    ///     userinfo (dict): information of user sending request.
    ///     query (ImmutableMultiDict): query string in URL.
    ///
    /// Raises:
    ///     ErrorPermissionDenied() if permission is not granted.
    ///
    /// Returns:
    ///     object containing requesting status value, or None on error or not
    ///     found.
    /// ```
    pub fn get_status_from_path(
        &mut self,
        plugins: &mut plugins_moxa_framework::status::Plugins,
        path: &str,
        userinfo: &user_info::UserInfo,
        query: &QString,
    ) -> Result<serde_json::Value, ErrorCommon> {
        let request_info = request_info::RequestInfo {
            method: http::Method::GET,
            path,
            userinfo: Some(userinfo.clone()),
            api_key: None,
            permissions: None,
        };

        if path.is_empty() {
            let mut return_status = serde_json::json!(null);

            for status_name in &self
                ._cache_info
                .keys()
                .map(|x| x.to_owned())
                .collect::<Vec<String>>()
            {
                if !self._check_status_permission(
                    plugins,
                    path,
                    userinfo,
                    status_name,
                    &request_info,
                )? {
                    continue;
                }
                self._update_status_cache(plugins, path, status_name, &request_info);
                return_status[status_name] = self._status[status_name].clone();
            }

            return Ok(return_status);
        }

        let path_vec: Vec<&str> = path.split('/').filter(|s| &"" != s).collect();
        let status_name = path_vec
            .first()
            .ok_or_else(|| ErrorCommon::new(ErrorType::InvalidRequestUri, path))?;

        if !self._check_status_permission(plugins, path, userinfo, status_name, &request_info)? {
            return Err(ErrorCommon::new(ErrorType::PermissionDenied, path));
        }

        self._update_status_cache(plugins, path, status_name, &request_info);
        self._get_status_by_path(path, query)
    }
}

