/// The trampoline the C side calls to size a table.
///
/// A panic is reported as -1, which the C side reads as "cannot tell" and
/// treats as an empty table - a walk still gets past it rather than stopping.
extern "C" fn row_count_trampoline(
    oid: *const c_ulong,
    oid_len: usize,
    ctx: *mut c_void,
) -> c_long {
    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        if ctx.is_null() || oid.is_null() || oid_len == 0 {
            return -1;
        }
        // SAFETY: same contract as `trampoline` - ctx is the address of the Box
        // owned by the live Session, and oid is valid for this call only.
        unsafe {
            let counter = &mut *(ctx as *mut RowCounter);
            #[allow(clippy::useless_conversion)]
            let subids: Vec<u64> = std::slice::from_raw_parts(oid, oid_len)
                .iter()
                .map(|&v| u64::from(v))
                .collect();
            counter(&subids)
        }
    }));

    result.unwrap_or(-1) as c_long
}

