/// Install the row-count handler used by every registered table.
///
/// Must be set before `register_iter_table`; a table registered without one
/// reports no rows. The closure is given the entry OID it was registered
/// with and returns the current row count, or a negative number for "cannot
/// tell", which reads as an empty table.
pub fn set_row_count_handler<F>(&mut self, counter: F)
where
    F: FnMut(&[u64]) -> i64 + 'static,
{
    let mut boxed: Box<RowCounter> = Box::new(Box::new(counter));
    let ctx = &mut *boxed as *mut RowCounter as *mut c_void;
    // SAFETY: ctx stays valid until clear_row_count_handler or drop, both
    // of which unregister before releasing the box.
    unsafe { mx_agentx_set_row_count_handler(Some(row_count_trampoline), ctx) };
    self.row_counter = Some(boxed);
}

