1	/*
2	 * lib_moxa_snmp_agentx - AgentX subagent shim for app_moxa_framework.
3	 *
4	 * Derived from FRR's lib/agentx.c, which solves the same problem against a
5	 * different reactor. The init sequence, the select/read/timeout cycle and the
6	 * non-blocking guard in mx_agentx_handle_read() all come from there.
7	 */
8	
9	#include <net-snmp/net-snmp-config.h>
10	#include <net-snmp/net-snmp-includes.h>
11	#include <net-snmp/agent/net-snmp-agent-includes.h>
12	#include <net-snmp/agent/table_iterator.h>
13	#include <net-snmp/library/large_fd_set.h>
14	
15	#include <errno.h>
16	#include <fcntl.h>
17	#include <stdlib.h>
18	#include <string.h>
19	
20	#include "lib_moxa_snmp_agentx/agentx.h"
21	
22	/*
23	 * The public API passes OID subidentifiers as unsigned long so the Rust FFI
24	 * does not need net-snmp's headers. That is only sound while net-snmp's oid
25	 * typedef is the same width, so the casts below are checked here rather than
26	 * assumed. On this target oid is unsigned long (library/oid.h:17).
27	 */
28	typedef char mx_agentx_oid_width_check
29	    [(sizeof(oid) == sizeof(unsigned long)) ? 1 : -1];
30	
31	static mx_agentx_get_cb        g_get_cb;
32	static void                   *g_get_ctx;
33	static mx_agentx_row_count_cb  g_row_count_cb;
34	static void                   *g_row_count_ctx;
35	static int                     g_initialised;
36	static char                    g_name[64];
37	
38	/*
39	 * The one in-flight request.
40	 *
41	 * Every net-snmp call in this library runs on the caller's single thread, and
42	 * the dispatcher invokes the handler synchronously, so at most one request is
43	 * ever open. A table would be dead weight. The id is a generation counter
44	 * rather than an index: it exists so that a reply arriving for a request that
45	 * has already been closed is rejected instead of writing into a varbind that
46	 * net-snmp has moved on from.
47	 */
48	static netsnmp_agent_request_info *g_cur_reqinfo;
49	static netsnmp_request_info       *g_cur_request;
50	static unsigned long               g_cur_req_id;
51	static unsigned long               g_next_req_id = 1;
52	
53	static netsnmp_request_info *
54	mx_agentx_claim(unsigned long req)
55	{
56	    if (g_cur_request == NULL || req != g_cur_req_id) {
57	        return NULL;
58	    }
59	    return g_cur_request;
60	}
61	
62	/*
63	 * Ask the Rust handler for every varbind in the chain, answering each from the
64	 * OID sitting in its requestvb. Both dispatchers below reach this point having
65	 * already decided that the OIDs are ready to be answered - which for GETNEXT is
66	 * only true once the table_iterator helper has resolved them.
67	 */
68	static void
69	mx_agentx_answer(netsnmp_agent_request_info *reqinfo,
70	                 netsnmp_request_info *requests)
71	{
72	    netsnmp_request_info *req;
73	
74	    for (req = requests; req != NULL; req = req->next) {
75	        int rc;
76	
77	        if (g_get_cb == NULL) {
78	            netsnmp_set_request_error(reqinfo, req, SNMP_NOSUCHOBJECT);
79	            continue;
80	        }
81	
82	        g_cur_reqinfo = reqinfo;
83	        g_cur_request = req;
84	        g_cur_req_id  = g_next_req_id++;
85	
86	        rc = g_get_cb(g_cur_req_id,
87	                      (const unsigned long *) req->requestvb->name,
88	                      req->requestvb->name_length,
89	                      g_get_ctx);
90	
91	        /*
92	         * Either the handler reported failure, or it returned without calling
93	         * one of mx_agentx_reply_* (which is what clears g_cur_request).
94	         * Both mean there is no value for this OID.
95	         */
96	        if (rc != 0 || g_cur_request != NULL) {
97	            netsnmp_set_request_error(reqinfo, req, SNMP_NOSUCHOBJECT);
98	        }
99	
100	        g_cur_request = NULL;
101	        g_cur_reqinfo = NULL;
102	    }
103	}
104	
105	static int
106	mx_agentx_dispatch(netsnmp_mib_handler *handler,
107	                   netsnmp_handler_registration *reginfo,
108	                   netsnmp_agent_request_info *reqinfo,
109	                   netsnmp_request_info *requests)
110	{
111	    (void) handler;
112	    (void) reginfo;
113	
114	    /*
115	     * GET only. SET never moves off in-master (design section 6.2), and a bare
116	     * arc registration gives net-snmp nothing to traverse, so there is no
117	     * resolved OID to answer a GETNEXT from. Tables that must walk register
118	     * through mx_agentx_register_iter_table() instead.
119	     */
120	    if (reqinfo->mode != MODE_GET) {
121	        return SNMP_ERR_NOERROR;
122	    }
123	
124	    mx_agentx_answer(reqinfo, requests);
125	    return SNMP_ERR_NOERROR;
126	}
127	
128	/*
129	 * One table registered through the iterator helper. Allocated per
130	 * registration and never freed: net-snmp keeps the pointer for the life of the
131	 * process, and the process has no path that unregisters.
132	 */
133	struct mx_agentx_table {
134	    unsigned long arc[MAX_OID_LEN];
135	    size_t        arc_len;
136	};
137	
138	/* Per-traversal state. The row count is read once at the start of a walk
139	 * rather than per row: it costs a read of the underlying data source, and a
140	 * count that changed mid-walk would produce a walk that skips or repeats. */
141	struct mx_agentx_loop {
142	    long row;
143	    long count;
144	};
145	
146	static netsnmp_variable_list *
147	mx_agentx_table_next(void **loop_ctx, void **data_ctx,
148	                     netsnmp_variable_list *put_index,
